To convert markdown formatted text to HTML in C++, you can use a library like `cppmark`, which is a popular markdown parser. Here's a function that takes a reference to a `std::string` containing markdown formatted text and returns a `std::string` containing HTML formatted text:

```cpp
#include <iostream>
#include <string>
#include "markdown markdown.h"
#include "cppmark/renderer.h"

std::string markdownToHtml(const std::string& markdownText) {
    // Create a new markdown parser
    markdown_parser markdownParser;

    // Convert the markdown text to HTML
    html_writer htmlWriter;
    markdownParser.convert(markdownText, htmlWriter);

    // Return the HTML text
    return htmlWriter.get_html();
}

int main() {
    std::string markdownText = "# Markdown Sample\n\nThis is a sample markdown text.";
    std::string htmlText = markdownToHtml(markdownText);
    std::cout << "HTML Text: " << htmlText << std::endl;
    return 0;
}
```

